//
// Run bedClip and bedGraphToBigWig
//

include { UCSC_BEDCLIP          } from 'nf-core/ucsc/bedclip'
include { UCSC_BEDGRAPHTOBIGWIG } from 'nf-core/ucsc/bedgraphtobigwig'

workflow BEDGRAPH_BEDCLIP_BEDGRAPHTOBIGWIG {
    take:
    bedgraph // channel: [ val(meta), [ bedgraph ] ]
    sizes    //    path: chrom.sizes

    main:

    //
    // Clip bedGraph file
    //
    UCSC_BEDCLIP ( bedgraph, sizes )

    //
    // Convert bedGraph to bigWig
    //
    UCSC_BEDGRAPHTOBIGWIG ( UCSC_BEDCLIP.out.bedgraph, sizes )

    emit:
    bigwig   = UCSC_BEDGRAPHTOBIGWIG.out.bigwig // channel: [ val(meta), [ bigwig ] ]
    bedgraph = UCSC_BEDCLIP.out.bedgraph        // channel: [ val(meta), [ bedgraph ] ]
}

nextflow_workflow {

    name "Test Workflow BEDGRAPH_BEDCLIP_BEDGRAPHTOBIGWIG"
    script "../main.nf"
    workflow "BEDGRAPH_BEDCLIP_BEDGRAPHTOBIGWIG"
    config "./nextflow.config"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bedgraph_bedclip_bedgraphtobigwig"
    tag "bedgraph_bedclip_bedgraphtobigwig"
    tag "ucsc"
    tag "ucsc/bedclip"
    tag "ucsc/bedgraphtobigwig"

    test("sarscov2 [bedgraph] [genome_sizes]") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bedgraph/test.bedgraph', checkIfExists: true)
                ])
                input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.sizes', checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("sarscov2 [bedgraph] [genome_sizes] - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bedgraph/test.bedgraph', checkIfExists: true)
                ])
                input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.sizes', checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}

